-- BEGIN 20260611120000_add_site_seo_keywords.sql
alter table public.site_settings
  add column if not exists seo_keywords jsonb not null default '["บ้านพักพูลวิลล่า","พูลวิลล่าพัทยา","บ้านพูลวิลล่าพัทยา","บ้านพักพูลวิลล่าพัทยา","บ้านพักสระส่วนตัว","พูลวิลล่าใกล้ทะเล","บ้านพักพัทยา","พูลวิลล่าจอมเทียน","พูลวิลล่าบางแสน","พูลวิลล่าหัวหิน"]'::jsonb,
  add column if not exists search_seo_keywords jsonb not null default '["ค้นหาพูลวิลล่าพัทยา","ค้นหาบ้านพักพูลวิลล่า","บ้านพักพูลวิลล่าตามราคา","พูลวิลล่าตามจำนวนคน","พูลวิลล่าตามทำเล"]'::jsonb,
  add column if not exists guides_seo_keywords jsonb not null default '["บทความพูลวิลล่าพัทยา","คู่มือเลือกพูลวิลล่า","แนะนำบ้านพักพูลวิลล่า","เที่ยวพัทยาพักพูลวิลล่า"]'::jsonb,
  add column if not exists villa_detail_seo_keywords jsonb not null default '["รายละเอียดพูลวิลล่าพัทยา","จองพูลวิลล่าพัทยา","บ้านพักพูลวิลล่ารายหลัง","พูลวิลล่าสระส่วนตัว"]'::jsonb;

update public.site_settings
set
  seo_keywords = case
    when jsonb_typeof(seo_keywords) = 'array' and jsonb_array_length(seo_keywords) > 0
      then seo_keywords
    else '["บ้านพักพูลวิลล่า","พูลวิลล่าพัทยา","บ้านพูลวิลล่าพัทยา","บ้านพักพูลวิลล่าพัทยา","บ้านพักสระส่วนตัว","พูลวิลล่าใกล้ทะเล","บ้านพักพัทยา","พูลวิลล่าจอมเทียน","พูลวิลล่าบางแสน","พูลวิลล่าหัวหิน"]'::jsonb
  end,
  search_seo_keywords = case
    when jsonb_typeof(search_seo_keywords) = 'array'
      then search_seo_keywords
    else '["ค้นหาพูลวิลล่าพัทยา","ค้นหาบ้านพักพูลวิลล่า","บ้านพักพูลวิลล่าตามราคา","พูลวิลล่าตามจำนวนคน","พูลวิลล่าตามทำเล"]'::jsonb
  end,
  guides_seo_keywords = case
    when jsonb_typeof(guides_seo_keywords) = 'array'
      then guides_seo_keywords
    else '["บทความพูลวิลล่าพัทยา","คู่มือเลือกพูลวิลล่า","แนะนำบ้านพักพูลวิลล่า","เที่ยวพัทยาพักพูลวิลล่า"]'::jsonb
  end,
  villa_detail_seo_keywords = case
    when jsonb_typeof(villa_detail_seo_keywords) = 'array'
      then villa_detail_seo_keywords
    else '["รายละเอียดพูลวิลล่าพัทยา","จองพูลวิลล่าพัทยา","บ้านพักพูลวิลล่ารายหลัง","พูลวิลล่าสระส่วนตัว"]'::jsonb
  end
where id is not null;

notify pgrst, 'reload schema';
-- END 20260611120000_add_site_seo_keywords.sql

-- BEGIN 20260623010000_add_site_seo_share_asset_uploads.sql
alter table public.site_asset_uploads
  drop constraint if exists site_asset_uploads_asset_type_check;

alter table public.site_asset_uploads
  add constraint site_asset_uploads_asset_type_check
  check (
    asset_type in (
      'logo',
      'hero',
      'seo-og',
      'search-seo-og',
      'guides-seo-og'
    )
  );

drop policy if exists "Authenticated admins can insert site asset uploads"
  on public.site_asset_uploads;

create policy "Authenticated admins can insert site asset uploads"
  on public.site_asset_uploads
  for insert
  to authenticated
  with check (
    private.is_home_config_admin()
    and storage_bucket = 'site-assets'
    and (
      storage_path like 'hero/%'
      or storage_path like 'logo/%'
      or storage_path like 'seo-og/%'
      or storage_path like 'search-seo-og/%'
      or storage_path like 'guides-seo-og/%'
    )
  );

drop policy if exists "Authenticated admins can update site asset uploads"
  on public.site_asset_uploads;

create policy "Authenticated admins can update site asset uploads"
  on public.site_asset_uploads
  for update
  to authenticated
  using (private.is_home_config_admin())
  with check (
    private.is_home_config_admin()
    and storage_bucket = 'site-assets'
    and (
      storage_path like 'hero/%'
      or storage_path like 'logo/%'
      or storage_path like 'seo-og/%'
      or storage_path like 'search-seo-og/%'
      or storage_path like 'guides-seo-og/%'
    )
  );

drop policy if exists "Authenticated admins can insert site assets"
  on storage.objects;

create policy "Authenticated admins can insert site assets"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'site-assets'
    and private.is_home_config_admin()
    and (
      name like 'hero/%'
      or name like 'logo/%'
      or name like 'seo-og/%'
      or name like 'search-seo-og/%'
      or name like 'guides-seo-og/%'
    )
  );

drop policy if exists "Authenticated admins can update site assets"
  on storage.objects;

create policy "Authenticated admins can update site assets"
  on storage.objects
  for update
  to authenticated
  using (
    bucket_id = 'site-assets'
    and private.is_home_config_admin()
    and (
      name like 'hero/%'
      or name like 'logo/%'
      or name like 'seo-og/%'
      or name like 'search-seo-og/%'
      or name like 'guides-seo-og/%'
    )
  )
  with check (
    bucket_id = 'site-assets'
    and private.is_home_config_admin()
    and (
      name like 'hero/%'
      or name like 'logo/%'
      or name like 'seo-og/%'
      or name like 'search-seo-og/%'
      or name like 'guides-seo-og/%'
    )
  );

drop policy if exists "Authenticated admins can delete site assets"
  on storage.objects;

create policy "Authenticated admins can delete site assets"
  on storage.objects
  for delete
  to authenticated
  using (
    bucket_id = 'site-assets'
    and private.is_home_config_admin()
    and (
      name like 'hero/%'
      or name like 'logo/%'
      or name like 'seo-og/%'
      or name like 'search-seo-og/%'
      or name like 'guides-seo-og/%'
    )
  );

notify pgrst, 'reload schema';
-- END 20260623010000_add_site_seo_share_asset_uploads.sql

-- BEGIN 20260703000000_add_site_link_bank_color_settings.sql
alter table public.site_settings
  add column if not exists header_link_color text not null default '#ffffff',
  add column if not exists header_link_hover_color text not null default '#eab308',
  add column if not exists footer_link_color text not null default '#ffffff',
  add column if not exists footer_link_hover_color text not null default '#eab308',
  add column if not exists bank_highlight_color text not null default '#eab308';

update public.site_settings
set
  header_link_color = case
    when header_link_color ~ '^#[0-9A-Fa-f]{6}$' then lower(header_link_color)
    else '#ffffff'
  end,
  header_link_hover_color = case
    when header_link_hover_color ~ '^#[0-9A-Fa-f]{6}$' then lower(header_link_hover_color)
    else '#eab308'
  end,
  footer_link_color = case
    when footer_link_color ~ '^#[0-9A-Fa-f]{6}$' then lower(footer_link_color)
    else '#ffffff'
  end,
  footer_link_hover_color = case
    when footer_link_hover_color ~ '^#[0-9A-Fa-f]{6}$' then lower(footer_link_hover_color)
    else '#eab308'
  end,
  bank_highlight_color = case
    when bank_highlight_color ~ '^#[0-9A-Fa-f]{6}$' then lower(bank_highlight_color)
    else '#eab308'
  end
where id = 'global';

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'site_settings_header_link_color_hex'
  ) then
    alter table public.site_settings
      add constraint site_settings_header_link_color_hex
      check (header_link_color ~ '^#[0-9A-Fa-f]{6}$');
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'site_settings_header_link_hover_color_hex'
  ) then
    alter table public.site_settings
      add constraint site_settings_header_link_hover_color_hex
      check (header_link_hover_color ~ '^#[0-9A-Fa-f]{6}$');
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'site_settings_footer_link_color_hex'
  ) then
    alter table public.site_settings
      add constraint site_settings_footer_link_color_hex
      check (footer_link_color ~ '^#[0-9A-Fa-f]{6}$');
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'site_settings_footer_link_hover_color_hex'
  ) then
    alter table public.site_settings
      add constraint site_settings_footer_link_hover_color_hex
      check (footer_link_hover_color ~ '^#[0-9A-Fa-f]{6}$');
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'site_settings_bank_highlight_color_hex'
  ) then
    alter table public.site_settings
      add constraint site_settings_bank_highlight_color_hex
      check (bank_highlight_color ~ '^#[0-9A-Fa-f]{6}$');
  end if;
end;
$$;

notify pgrst, 'reload schema';
-- END 20260703000000_add_site_link_bank_color_settings.sql

-- BEGIN 20260703001000_add_site_logo_background_setting.sql
alter table public.site_settings
  add column if not exists logo_background text not null default 'white';

update public.site_settings
set logo_background = case
  when logo_background in ('white', 'transparent', 'primary', 'soft') then logo_background
  else 'white'
end
where id = 'global';

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'site_settings_logo_background_allowed'
  ) then
    alter table public.site_settings
      add constraint site_settings_logo_background_allowed
      check (logo_background in ('white', 'transparent', 'primary', 'soft'));
  end if;
end;
$$;

notify pgrst, 'reload schema';
-- END 20260703001000_add_site_logo_background_setting.sql

