notify pgrst, 'reload schema';

select
  (
    select count(*)
    from public.site_seo_settings
    where page_type in ('global', 'search', 'guides', 'villa_detail')
  ) as canonical_row_count,
  (
    select count(*)
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'site_settings'
      and column_name in (
        'seo_title',
        'seo_description',
        'seo_keywords',
        'seo_og_image_url',
        'seo_og_image_alt',
        'seo_business_name',
        'seo_same_as_urls',
        'search_seo_title',
        'search_seo_description',
        'search_seo_keywords',
        'search_seo_og_image_url',
        'search_seo_og_image_alt',
        'guides_seo_title',
        'guides_seo_description',
        'guides_seo_keywords',
        'guides_seo_og_image_url',
        'guides_seo_og_image_alt',
        'villa_detail_seo_keywords'
      )
  ) as legacy_column_count,
  (
    select count(*)
    from pg_catalog.pg_proc function_definition
    join pg_catalog.pg_namespace function_schema
      on function_schema.oid = function_definition.pronamespace
    where function_definition.prokind in ('f', 'p')
      and function_schema.nspname !~ '^pg_'
      and function_schema.nspname <> 'information_schema'
      and exists (
        select 1
        from unnest(array[
          'seo_title',
          'seo_description',
          'seo_keywords',
          'seo_og_image_url',
          'seo_og_image_alt',
          'seo_business_name',
          'seo_same_as_urls',
          'search_seo_title',
          'search_seo_description',
          'search_seo_keywords',
          'search_seo_og_image_url',
          'search_seo_og_image_alt',
          'guides_seo_title',
          'guides_seo_description',
          'guides_seo_keywords',
          'guides_seo_og_image_url',
          'guides_seo_og_image_alt',
          'villa_detail_seo_keywords'
        ]) legacy_column
        where position(legacy_column in lower(pg_catalog.pg_get_functiondef(function_definition.oid))) > 0
      )
  ) as dependency_count;
-- END 20260716080413_contract_site_seo_settings.sql

-- BEGIN 20260716114748_add_detail_parking_block.sql
update public.site_settings
set detail_layout = jsonb_set(
  detail_layout,
  '{rows}',
  (detail_layout -> 'rows') || jsonb_build_array(jsonb_build_object(
    'id', 'row_parking',
    'columns', 1,
    'enabled', true,
    'blocks', jsonb_build_array(jsonb_build_object(
      'type', 'parking',
      'title', 'ที่จอดรถ',
      'enabled', true,
      'hideWhenEmpty', true
    ))
  ))
)
where detail_layout ->> 'version' = '1'
  and jsonb_typeof(detail_layout -> 'rows') = 'array'
  and not jsonb_path_exists(detail_layout, '$.** ? (@.type == "parking")');

update public.site_settings
set detail_layout = jsonb_set(
  detail_layout,
  '{mainSplit,wideRows}',
  (detail_layout #> '{mainSplit,wideRows}') || jsonb_build_array(jsonb_build_object(
    'id', 'row_parking',
    'columns', 1,
    'enabled', true,
    'blocks', jsonb_build_array(jsonb_build_object(
      'type', 'parking',
      'title', 'ที่จอดรถ',
      'enabled', true,
      'hideWhenEmpty', true
    ))
  ))
)
where detail_layout ->> 'version' = '2'
