-- BEGIN 20260730171122_repair_reconciled_admin_list_integer_cast.sql
create or replace function private.list_reconciled_admin_users_v1_impl(
  p_page integer,
  p_page_size integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_offset integer;
  v_result jsonb;
begin
  if p_page is null
    or not (p_page between 1 and 100)
    or p_page_size is null
    or not (p_page_size between 1 and 100)
  then
    raise exception using
      errcode = 'P0001',
      message = 'profile_data_invalid';
  end if;

  v_offset := (p_page - 1) * p_page_size;

  with auth_source as (
    select
      u.id as user_id,
      pg_catalog.lower(pg_catalog.btrim(u.email)) as auth_email,
      u.created_at as auth_created_at,
      u.last_sign_in_at,
      u.confirmed_at,
      u.banned_until,
      (
        u.raw_app_meta_data -> 'bpv_admin_managed'
          = 'true'::pg_catalog.jsonb
      ) as auth_managed,
      case
        when pg_catalog.jsonb_typeof(
          u.raw_app_meta_data -> 'credential_version'
        ) = 'number'
          and (u.raw_app_meta_data ->> 'credential_version')
            ~ '^[1-9][0-9]{0,9}$'
          and (u.raw_app_meta_data ->> 'credential_version')::pg_catalog.numeric
            <= 2147483647
        then (u.raw_app_meta_data ->> 'credential_version')::pg_catalog.int4
        else null
      end as auth_credential_version
    from auth.users as u
    where u.email is not null
      and pg_catalog.btrim(u.email) <> ''
  ),
  profile_source as (
    select
      p.user_id,
      pg_catalog.lower(pg_catalog.btrim(p.email)) as profile_email,
      p.role,
      p.is_active,
      p.must_change_password,
      p.credential_version,
      p.created_at as profile_created_at
    from public.admin_users as p
  ),
  email_claims as (
    select auth_email as normalized_email, user_id from auth_source
    union
    select profile_email as normalized_email, user_id from profile_source
  ),
  email_ownership as (
    select normalized_email, pg_catalog.count(*) as owner_count
    from email_claims
    where normalized_email is not null
      and normalized_email <> ''
    group by normalized_email
  ),
  joined as (
    select
      coalesce(a.user_id, p.user_id) as user_id,
      coalesce(a.auth_email, p.profile_email) as display_email,
      a.auth_email,
      p.profile_email,
      a.auth_created_at,
      p.profile_created_at,
      a.last_sign_in_at,
      a.confirmed_at,
      a.banned_until,
      a.auth_managed,
      a.auth_credential_version,
      p.role,
      p.is_active,
      p.must_change_password,
      p.credential_version,
      a.user_id is not null as has_auth,
      p.user_id is not null as has_profile,
      coalesce(auth_owners.owner_count, 0) as auth_email_owners,
      coalesce(profile_owners.owner_count, 0) as profile_email_owners
    from auth_source as a
    full outer join profile_source as p
      on a.user_id = p.user_id
    left join email_ownership as auth_owners
      on auth_owners.normalized_email = a.auth_email
    left join email_ownership as profile_owners
      on profile_owners.normalized_email = p.profile_email
  ),
  assessed as (
    select
      user_id,
      display_email,
      case
        when not has_auth
          or not has_profile
          or display_email is null
          or display_email = ''
          or auth_email is distinct from profile_email
          or role is distinct from 'admin'
          or auth_managed is distinct from true
          or confirmed_at is null
          or auth_credential_version is null
          or credential_version is null
          or credential_version <= 0
          or auth_credential_version is distinct from credential_version
          or auth_email_owners > 1
          or profile_email_owners > 1
          or (
            is_active
            and banned_until is not null
            and banned_until > pg_catalog.statement_timestamp()
          )
          or (
            not is_active
            and (
              banned_until is null
              or banned_until <= pg_catalog.statement_timestamp()
            )
          )
        then 'abnormal'
        when not is_active then 'suspended'
        when must_change_password then 'password_change_required'
        else 'active'
      end as status,
      coalesce(auth_created_at, profile_created_at) as created_at,
      last_sign_in_at,
      credential_version,
      auth_credential_version
    from joined
  ),
  page_rows as (
    select *
    from assessed
    order by display_email asc, user_id asc
    offset v_offset
    limit p_page_size + 1
  ),
  numbered_page as (
    select
      page_rows.*,
      pg_catalog.row_number() over (
        order by display_email asc, user_id asc
      ) as page_position
    from page_rows
  )
  select pg_catalog.jsonb_build_object(
    'users',
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'userId', user_id,
          'email', display_email,
          'status', status,
          'createdAt', created_at,
          'lastSignInAt', last_sign_in_at,
          'credentialVersion', credential_version,
          'authCredentialVersion', auth_credential_version
        )
        order by display_email asc, user_id asc
      ) filter (where page_position <= p_page_size),
      '[]'::pg_catalog.jsonb
    ),
    'hasMore',
    p_page < 100 and pg_catalog.count(*) > p_page_size
  )
  into v_result
  from numbered_page;

  return v_result;
end;
$$;

revoke all on function private.list_reconciled_admin_users_v1_impl(
  integer,
  integer
) from public, anon, authenticated, service_role;
-- END 20260730171122_repair_reconciled_admin_list_integer_cast.sql

-- BEGIN 20260731075339_repair_reactivation_provider_chain.sql
create or replace function private.commit_admin_user_provider_intent_v2_impl(
  p_operation_id uuid,
  p_fence_version integer,
  p_lease_token_hash text,
  p_provider_step text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, extensions
as $$
declare
  v_operation public.admin_user_operations%rowtype;
  v_target_email_normalized text;
  v_expected_stage text;
  v_expected_status text;
  v_step_ordinal integer;
  v_now timestamptz := clock_timestamp();
begin
  select target_email_normalized
  into strict v_target_email_normalized
  from public.admin_user_operations
  where operation_id = p_operation_id;

  perform pg_advisory_xact_lock(
    hashtextextended(v_target_email_normalized, 0)
  );

  select *
  into strict v_operation
  from public.admin_user_operations
  where operation_id = p_operation_id
  for update;

  if v_operation.action = 'create_user'
    and p_provider_step = 'auth_create'
  then
    v_expected_stage := 'claimed';
    v_expected_status := 'leased';
    v_step_ordinal := 1;
  elsif v_operation.action = 'create_user'
    and p_provider_step = 'auth_delete'
  then
    v_expected_stage := 'compensation_ready';
    v_expected_status := 'leased';
    v_step_ordinal := 2;
  elsif v_operation.action in (
      'reissue_temporary_password',
      'suspend_user',
      'reactivate_user'
    )
    and p_provider_step = 'auth_update'
  then
    v_expected_stage := 'profile_advanced';
    v_expected_status := 'leased';
    v_step_ordinal := 1;
  elsif v_operation.action in (
      'reissue_temporary_password',
      'reactivate_user'
    )
    and p_provider_step = 'password_verify'
  then
    v_expected_stage := 'auth_update_succeeded';
    v_expected_status := 'provider_outcome';
    v_step_ordinal := 2;
  elsif v_operation.action in (
      'reissue_temporary_password',
      'reactivate_user'
    )
    and p_provider_step = 'global_signout'
  then
    v_expected_stage := 'password_verify_succeeded';
    v_expected_status := 'provider_outcome';
    v_step_ordinal := 3;
  else
    raise exception using errcode = 'P0001', message = 'operation_conflict';
  end if;

  if v_operation.stage is distinct from v_expected_stage
    or v_operation.status is distinct from v_expected_status
    or v_operation.fence_version is distinct from p_fence_version
    or v_operation.lease_token_hash is distinct from p_lease_token_hash
    or v_operation.lease_expires_at is null
    or v_operation.lease_expires_at <= v_now
  then
    raise exception using errcode = 'P0001', message = 'operation_conflict';
  end if;

  perform 1
  from public.admin_user_mutation_locks
  where target_email_normalized = v_target_email_normalized
    and operation_id = p_operation_id
    and fence_version = p_fence_version
    and lease_token_hash = p_lease_token_hash
    and state = 'leased'
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'lease_lost';
  end if;

  insert into public.admin_user_provider_events (
    operation_id,
    provider_step,
    step_ordinal
  )
  values (p_operation_id, p_provider_step, v_step_ordinal);

  update public.admin_user_operations
  set status = 'provider_intent',
      stage = p_provider_step || '_intent',
      provider_intent_at = v_now,
      updated_at = v_now
  where operation_id = p_operation_id
  returning * into strict v_operation;

  return private.admin_user_operation_record(v_operation);
end;
$$;

revoke all on function private.commit_admin_user_provider_intent_v2_impl(
  uuid,
  integer,
  text,
  text
) from public, anon, authenticated, service_role;

do $$
declare
  v_candidate record;
  v_operation public.admin_user_operations%rowtype;
  v_lock public.admin_user_mutation_locks%rowtype;
  v_fence public.admin_user_mutation_fences%rowtype;
  v_event public.admin_user_provider_events%rowtype;
  v_profile public.admin_users%rowtype;
  v_auth_user auth.users%rowtype;
  v_credential_version integer;
  v_auth_managed boolean;
  v_auth_credential_version integer;
  v_now timestamptz := clock_timestamp();
begin
  for v_candidate in
    select operation_id, target_email_normalized
    from public.admin_user_operations
    where action = 'reactivate_user'
      and status = 'provider_outcome'
      and stage = 'auth_update_succeeded'
      and lease_expires_at is not null
      and lease_expires_at <= v_now
  loop
    perform pg_advisory_xact_lock(
      hashtextextended(v_candidate.target_email_normalized, 0)
    );

    select *
    into v_operation
    from public.admin_user_operations
    where operation_id = v_candidate.operation_id
    for update;

    if not found
      or v_operation.action is distinct from 'reactivate_user'
      or v_operation.status is distinct from 'provider_outcome'
      or v_operation.stage is distinct from 'auth_update_succeeded'
      or v_operation.target_user_id is null
      or v_operation.target_email_normalized is null
      or v_operation.lease_token_hash is null
      or v_operation.lease_expires_at is null
      or v_operation.lease_expires_at > v_now
      or v_operation.safe_error_code is not null
    then
      continue;
    end if;

    begin
      v_credential_version :=
        (v_operation.safe_result ->> 'credentialVersion')::integer;
    exception
      when others then
        continue;
    end;

    if v_credential_version <= 0
      or v_operation.safe_result ->> 'providerStep' is distinct from
        'auth_update'
      or v_operation.safe_result ->> 'outcome' is distinct from 'succeeded'
      or v_operation.safe_result ->> 'userId' is distinct from
        v_operation.target_user_id::text
    then
      continue;
    end if;

    select *
    into v_lock
    from public.admin_user_mutation_locks
    where target_email_normalized = v_operation.target_email_normalized
    for update;

    if not found
      or v_lock.state is distinct from 'leased'
      or v_lock.owner_kind is distinct from 'central_operation'
      or v_lock.operation_id is distinct from v_operation.operation_id
      or v_lock.fence_version is distinct from v_operation.fence_version
      or v_lock.lease_token_hash is distinct from
        v_operation.lease_token_hash
      or v_lock.lease_expires_at > v_now
    then
      continue;
    end if;

    select *
    into v_fence
    from public.admin_user_mutation_fences
    where target_email_normalized = v_operation.target_email_normalized
    for update;

    if not found
      or v_fence.is_quarantined
      or v_fence.last_fence_version is distinct from
        v_operation.fence_version
    then
      continue;
    end if;

    select *
    into v_event
    from public.admin_user_provider_events
    where operation_id = v_operation.operation_id
      and provider_step = 'auth_update'
    for update;

    if not found
      or v_event.provider_step is distinct from 'auth_update'
      or v_event.step_ordinal is distinct from 1
      or v_event.outcome is distinct from 'succeeded'
      or v_event.target_user_id is distinct from v_operation.target_user_id
      or v_event.credential_version is distinct from v_credential_version
      or v_event.provider_error_code is not null
      or v_event.outcome_at is null
    then
      continue;
    end if;

    select *
    into v_profile
    from public.admin_users
    where user_id = v_operation.target_user_id
      and email = v_operation.target_email_normalized
    for update;

    if not found
      or v_profile.is_active
      or v_profile.must_change_password is distinct from true
      or v_profile.credential_version is distinct from v_credential_version
    then
      continue;
    end if;

    select *
    into v_auth_user
    from auth.users
    where id = v_operation.target_user_id
      and lower(btrim(email)) = v_operation.target_email_normalized
    for update;

    if not found then
      continue;
    end if;

    begin
      v_auth_managed :=
        (v_auth_user.raw_app_meta_data ->> 'bpv_admin_managed')::boolean;
      v_auth_credential_version :=
        (v_auth_user.raw_app_meta_data ->> 'credential_version')::integer;
    exception
      when others then
        continue;
    end;

    if v_auth_managed is distinct from true
      or v_auth_credential_version is distinct from v_credential_version
      or v_auth_user.banned_until is null
      or v_auth_user.banned_until <= v_now
    then
      continue;
    end if;

    delete from public.admin_user_mutation_locks
    where target_email_normalized = v_operation.target_email_normalized
      and operation_id = v_operation.operation_id
      and fence_version = v_operation.fence_version
      and lease_token_hash = v_operation.lease_token_hash
      and state = 'leased'
      and lease_expires_at <= v_now;

    if not found then
      continue;
    end if;

    update public.admin_user_operations
    set status = 'needs_review',
        stage = 'needs_review',
        safe_error_code = 'profile_state_conflict',
        safe_error_message = 'Admin profile state changed.',
        lease_token_hash = null,
        lease_expires_at = null,
        updated_at = v_now
    where operation_id = v_operation.operation_id
      and status = 'provider_outcome'
      and stage = 'auth_update_succeeded'
      and fence_version = v_operation.fence_version
      and lease_token_hash = v_operation.lease_token_hash;

    if not found then
      raise exception using
        errcode = 'P0001',
        message = 'operation_conflict';
    end if;
  end loop;
end;
$$;

notify pgrst, 'reload schema';
-- END 20260731075339_repair_reactivation_provider_chain.sql

-- BEGIN 20260803100000_add_home_section_auto_scroll.sql
alter table public.home_sections
  add column if not exists auto_scroll_enabled boolean not null default false;

create or replace function public.save_home_section_snapshot(snapshot jsonb)
returns void
language plpgsql
security invoker
set search_path = public, private
as $$
begin
  perform private.save_home_section_snapshot(snapshot);

  update public.home_sections as stored_section
  set auto_scroll_enabled = coalesce(
    (snapshot_section.value ->> 'auto_scroll_enabled')::boolean,
    false
  )
  from jsonb_array_elements(
    coalesce(snapshot -> 'sections', '[]'::jsonb)
  ) as snapshot_section(value)
  where stored_section.slug = snapshot_section.value ->> 'slug';
end;
$$;

revoke all on function public.save_home_section_snapshot(jsonb) from public;
grant execute on function public.save_home_section_snapshot(jsonb) to authenticated;

notify pgrst, 'reload schema';
-- END 20260803100000_add_home_section_auto_scroll.sql

